WITH data AS (select value x from jsonb_array_elements($j$[{"language": "es", "slug": "cuajada-casera-con-cuajo", "total_time_minutes": 230, "summary": "Esta cuajada es un queso fresco tierno de cuajo, sin maduración ni prensado fuerte. Con 2 litros de leche salen unos 350–450 g. Necesitas termómetro, tela para queso y una jeringa graduada sin aguja para medir el cuajo.", "content_html": "<p>Esta cuajada es un queso fresco tierno de cuajo, sin maduración ni prensado fuerte. Con 2 litros de leche salen unos 350–450 g. Necesitas termómetro, tela para queso y una jeringa graduada sin aguja para medir el cuajo.</p>", "seo": {"title": "Cuajada casera con cuajo: queso fresco suave", "description": "Haz cuajada casera suave con leche pasteurizada y cuajo. Fotos para cuajar, cortar y escurrir, con dosis orientativa, rendimiento y conservación en frío.", "author": "Néstor Bastidas", "image_alt": "Cuajada casera con cuajo: queso fresco suave", "image_variants": ["https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-1x1.webp", "https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-4x3.webp", "https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-16x9.webp"], "faq": [{"q": "¿Cuajada es yogur?", "a": "Esta no: se coagula con cuajo, sin la fermentación del yogur."}, {"q": "¿Por qué no queda firme?", "a": "Puede influir la leche, el cuajo o la temperatura. Revisa la etiqueta y usa leche adecuada; no añadas cuajo a ciegas."}], "additional_time_minutes": 200}}, {"language": "en", "slug": "homemade-rennet-curds-cuajada", "total_time_minutes": 230, "summary": "Cuajada is a tender fresh rennet cheese without aging or heavy pressing. Two litres of milk yield about 350–450 g. Use a thermometer, cheesecloth and a graduated needle-free syringe for the rennet.", "content_html": "<p>Cuajada is a tender fresh rennet cheese without aging or heavy pressing. Two litres of milk yield about 350–450 g. Use a thermometer, cheesecloth and a graduated needle-free syringe for the rennet.</p>", "seo": {"title": "Homemade cuajada: soft fresh rennet cheese", "description": "Make soft cuajada with pasteurized milk and rennet. Photos show setting, cutting and draining, with a concentration-specific dose, yield and cold storage.", "author": "Néstor Bastidas", "image_alt": "Homemade cuajada: soft fresh rennet cheese", "image_variants": ["https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-1x1.webp", "https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-4x3.webp", "https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-16x9.webp"], "faq": [{"q": "Is cuajada yogurt?", "a": "This version is not: rennet sets the milk without yogurt fermentation."}, {"q": "Why is it too soft?", "a": "Milk, rennet or temperature may be responsible. Check the label and milk type; do not add rennet blindly."}], "additional_time_minutes": 200}}, {"language": "de", "slug": "cuajada-frischer-labkaese", "total_time_minutes": 230, "summary": "Cuajada ist ein zarter frischer Labkäse ohne Reifung oder starkes Pressen. Zwei Liter Milch ergeben etwa 350–450 g. Du brauchst Thermometer, Käsetuch und eine graduierte Spritze ohne Nadel fürs Lab.", "content_html": "<p>Cuajada ist ein zarter frischer Labkäse ohne Reifung oder starkes Pressen. Zwei Liter Milch ergeben etwa 350–450 g. Du brauchst Thermometer, Käsetuch und eine graduierte Spritze ohne Nadel fürs Lab.</p>", "seo": {"title": "Cuajada selber machen: weicher frischer Labkäse", "description": "Weiche Cuajada aus pasteurisierter Milch und Lab herstellen. Schrittfotos erklären Gerinnen, Schneiden und Abtropfen, mit Dosierung, Ausbeute und Kühlung.", "author": "Néstor Bastidas", "image_alt": "Cuajada selber machen: weicher frischer Labkäse", "image_variants": ["https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-1x1.webp", "https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-4x3.webp", "https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-16x9.webp"], "faq": [{"q": "Ist Cuajada Joghurt?", "a": "Diese Variante wird durch Lab fest und nicht wie Joghurt fermentiert."}, {"q": "Warum bleibt sie zu weich?", "a": "Milch, Lab und Temperatur beeinflussen das Ergebnis. Angaben prüfen und Lab nicht unkontrolliert nachgeben."}], "additional_time_minutes": 200}}, {"language": "fr", "slug": "cuajada-fromage-frais-presure", "total_time_minutes": 230, "summary": "La cuajada est un fromage frais tendre à la présure, sans affinage ni pressage fort. Deux litres de lait donnent environ 350–450 g. Prévoyez thermomètre, étamine et seringue graduée sans aiguille.", "content_html": "<p>La cuajada est un fromage frais tendre à la présure, sans affinage ni pressage fort. Deux litres de lait donnent environ 350–450 g. Prévoyez thermomètre, étamine et seringue graduée sans aiguille.</p>", "seo": {"title": "Cuajada maison : fromage frais tendre à la présure", "description": "Préparez une cuajada tendre avec du lait pasteurisé et de la présure. Photos du caillage, de la découpe et de l'égouttage, dosage, rendement et conservation.", "author": "Néstor Bastidas", "image_alt": "Cuajada maison : fromage frais tendre à la présure", "image_variants": ["https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-1x1.webp", "https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-4x3.webp", "https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-16x9.webp"], "faq": [{"q": "Est-ce un yaourt ?", "a": "Non : cette cuajada coagule à la présure, sans fermentation de yaourt."}, {"q": "Pourquoi reste-t-elle molle ?", "a": "Lait, présure ou température peuvent intervenir. Vérifiez les indications sans rajouter de présure au hasard."}], "additional_time_minutes": 200}}, {"language": "it", "slug": "cuajada-formaggio-fresco-caglio", "total_time_minutes": 230, "summary": "La cuajada è un formaggio fresco tenero, senza stagionatura o pressatura forte. Due litri di latte rendono circa 350–450 g. Servono termometro, telo da formaggio e siringa graduata senza ago.", "content_html": "<p>La cuajada è un formaggio fresco tenero, senza stagionatura o pressatura forte. Due litri di latte rendono circa 350–450 g. Servono termometro, telo da formaggio e siringa graduata senza ago.</p>", "seo": {"title": "Cuajada fatta in casa: formaggio fresco al caglio", "description": "Prepara la cuajada morbida con latte pastorizzato e caglio. Foto di coagulazione, taglio e scolatura, con dose legata alla concentrazione e conservazione.", "author": "Néstor Bastidas", "image_alt": "Cuajada fatta in casa: formaggio fresco al caglio", "image_variants": ["https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-1x1.webp", "https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-4x3.webp", "https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-16x9.webp"], "faq": [{"q": "È yogurt?", "a": "No: questa cuajada si coagula con caglio, senza fermentazione da yogurt."}, {"q": "Perché è troppo morbida?", "a": "Dipende anche da latte, caglio e temperatura. Controlla le indicazioni senza aggiungere caglio alla cieca."}], "additional_time_minutes": 200}}, {"language": "ja", "slug": "homemade-rennet-curds-cuajada", "total_time_minutes": 230, "summary": "クアハーダは熟成や強い圧搾をしない柔らかなフレッシュチーズです。牛乳2 Lで約350〜450 gできます。温度計、チーズ用の布、レンネット用の目盛り付き針なしシリンジを用意します。", "content_html": "<p>クアハーダは熟成や強い圧搾をしない柔らかなフレッシュチーズです。牛乳2 Lで約350〜450 gできます。温度計、チーズ用の布、レンネット用の目盛り付き針なしシリンジを用意します。</p>", "seo": {"title": "レンネットで作る柔らかな自家製クアハーダ", "description": "殺菌牛乳とレンネットで作る柔らかなクアハーダ。凝固、カット、水切りを写真で説明します。凝乳剤の濃度別の量、出来上がり量、冷蔵保存も確認できるレシピです。", "author": "Néstor Bastidas", "image_alt": "レンネットで作る柔らかな自家製クアハーダ", "image_variants": ["https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-1x1.webp", "https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-4x3.webp", "https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-16x9.webp"], "faq": [{"q": "ヨーグルトですか。", "a": "このレシピは違います。ヨーグルト発酵ではなく、レンネットで固めます。"}, {"q": "柔らかすぎるのはなぜですか。", "a": "牛乳、レンネット、温度が影響します。製品表示を確認し、むやみに凝乳剤を追加しないでください。"}], "additional_time_minutes": 200}}, {"language": "pt", "slug": "cuajada-caseira-com-coalho", "total_time_minutes": 230, "summary": "Cuajada é um queijo fresco tenro, sem maturação nem prensagem forte. Dois litros de leite rendem cerca de 350–450 g. Use termômetro, pano de queijo e seringa graduada sem agulha.", "content_html": "<p>Cuajada é um queijo fresco tenro, sem maturação nem prensagem forte. Dois litros de leite rendem cerca de 350–450 g. Use termômetro, pano de queijo e seringa graduada sem agulha.</p>", "seo": {"title": "Cuajada caseira: queijo fresco macio com coalho", "description": "Faça cuajada macia com leite pasteurizado e coalho. Fotos mostram coagulação, corte e drenagem, com dose conforme a concentração, rendimento e conservação.", "author": "Néstor Bastidas", "image_alt": "Cuajada caseira: queijo fresco macio com coalho", "image_variants": ["https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-1x1.webp", "https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-4x3.webp", "https://manualdecocina.com/recetas/cuajada-casera-con-cuajo/portada-16x9.webp"], "faq": [{"q": "É iogurte?", "a": "Esta versão não: coagula com coalho, sem a fermentação do iogurte."}, {"q": "Por que fica mole demais?", "a": "Leite, coalho e temperatura podem influenciar. Confira as instruções; não acrescente coalho sem medida."}], "additional_time_minutes": 200}}, {"language": "es", "slug": "requeson-casero-de-leche", "total_time_minutes": 190, "summary": "Esta versión de requesón se prepara con leche entera y limón y queda suelta y húmeda, parecida a una ricotta de leche. No es la ricotta tradicional hecha solo de suero. Con 2 litros salen unos 300–450 g; calculamos 350 g.", "content_html": "<p>Esta versión de requesón se prepara con leche entera y limón y queda suelta y húmeda, parecida a una ricotta de leche. No es la ricotta tradicional hecha solo de suero. Con 2 litros salen unos 300–450 g; calculamos 350 g.</p>", "seo": {"title": "Requesón casero de leche, suave y sin prensar", "description": "Prepara requesón casero de leche y limón, con textura suave para rellenos o desayunos. Fotos de cuajado y escurrido, rendimiento y conservación en nevera.", "author": "Néstor Bastidas", "image_alt": "Requesón casero de leche, suave y sin prensar", "image_variants": ["https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-1x1.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-4x3.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-16x9.webp"], "faq": [{"q": "¿Puedo usar solo suero?", "a": "No con estas cantidades: el suero tiene otras proteínas y otra acidez. Esta receta está formulada para leche."}, {"q": "¿Por qué queda seco?", "a": "Mucho escurrido, presión o hervor fuerte secan los copos. Escurre menos y sin peso."}], "additional_time_minutes": 160}}, {"language": "en", "slug": "homemade-whole-milk-ricotta", "total_time_minutes": 190, "summary": "This requeson-style cheese uses whole milk and lemon and stays loose and moist, like whole-milk ricotta. It is not traditional whey-only ricotta. Two litres yield about 300–450 g; the estimate here is 350 g.", "content_html": "<p>This requeson-style cheese uses whole milk and lemon and stays loose and moist, like whole-milk ricotta. It is not traditional whey-only ricotta. Two litres yield about 300–450 g; the estimate here is 350 g.</p>", "seo": {"title": "Homemade whole-milk ricotta, soft and unpressed", "description": "Make soft whole-milk ricotta with lemon juice for fillings and breakfasts. Photos explain curd formation, gentle draining, approximate yield and cold storage.", "author": "Néstor Bastidas", "image_alt": "Homemade whole-milk ricotta, soft and unpressed", "image_variants": ["https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-1x1.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-4x3.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-16x9.webp"], "faq": [{"q": "Can I use whey alone?", "a": "Not in these quantities: whey has different proteins and acidity. This recipe is formulated for milk."}, {"q": "Why is it dry?", "a": "Excess draining, pressing or vigorous boiling dries the curds. Drain less, without weights."}], "additional_time_minutes": 160}}, {"language": "de", "slug": "ricotta-aus-vollmilch-selber-machen", "total_time_minutes": 190, "summary": "Dieser Requesón aus Vollmilch und Zitrone bleibt locker und feucht, ähnlich Vollmilch-Ricotta. Er ist kein traditioneller Ricotta nur aus Molke. Zwei Liter ergeben etwa 300–450 g; gerechnet wird mit 350 g.", "content_html": "<p>Dieser Requesón aus Vollmilch und Zitrone bleibt locker und feucht, ähnlich Vollmilch-Ricotta. Er ist kein traditioneller Ricotta nur aus Molke. Zwei Liter ergeben etwa 300–450 g; gerechnet wird mit 350 g.</p>", "seo": {"title": "Weicher Ricotta aus Vollmilch ohne Pressen", "description": "Weichen Ricotta aus Vollmilch und Zitronensaft herstellen. Fotos erklären Flockenbildung, sanftes Abtropfen, ungefähre Ausbeute und gekühlte Aufbewahrung.", "author": "Néstor Bastidas", "image_alt": "Weicher Ricotta aus Vollmilch ohne Pressen", "image_variants": ["https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-1x1.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-4x3.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-16x9.webp"], "faq": [{"q": "Geht es nur mit Molke?", "a": "Nicht mit diesen Mengen: Molke hat andere Proteine und Säure. Dieses Rezept ist für Milch berechnet."}, {"q": "Warum wird er trocken?", "a": "Zu langes Abtropfen, Pressen oder starkes Kochen trocknet die Flocken. Kürzer und ohne Gewicht abtropfen."}], "additional_time_minutes": 160}}, {"language": "fr", "slug": "ricotta-maison-au-lait-entier", "total_time_minutes": 190, "summary": "Ce requesón au lait entier et au citron reste souple et humide, proche d'une ricotta de lait. Ce n'est pas une ricotta traditionnelle de petit-lait seul. Deux litres donnent environ 300–450 g ; nous comptons 350 g.", "content_html": "<p>Ce requesón au lait entier et au citron reste souple et humide, proche d&#x27;une ricotta de lait. Ce n&#x27;est pas une ricotta traditionnelle de petit-lait seul. Deux litres donnent environ 300–450 g ; nous comptons 350 g.</p>", "seo": {"title": "Ricotta maison au lait entier, sans pressage", "description": "Préparez une ricotta tendre au lait et au citron pour garnitures et petits-déjeuners. Photos du caillage, égouttage doux, rendement et conservation au frais.", "author": "Néstor Bastidas", "image_alt": "Ricotta maison au lait entier, sans pressage", "image_variants": ["https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-1x1.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-4x3.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-16x9.webp"], "faq": [{"q": "Puis-je utiliser seulement du petit-lait ?", "a": "Pas avec ces proportions : protéines et acidité diffèrent. Cette recette est prévue pour du lait."}, {"q": "Pourquoi est-elle sèche ?", "a": "Égouttage long, pressage et forte ébullition dessèchent les flocons. Égouttez moins et sans poids."}], "additional_time_minutes": 160}}, {"language": "it", "slug": "ricotta-casalinga-di-latte-intero", "total_time_minutes": 190, "summary": "Questo requesón di latte intero e limone rimane morbido e umido, simile a una ricotta di latte. Non è la ricotta tradizionale di solo siero. Due litri rendono circa 300–450 g; qui calcoliamo 350 g.", "content_html": "<p>Questo requesón di latte intero e limone rimane morbido e umido, simile a una ricotta di latte. Non è la ricotta tradizionale di solo siero. Due litri rendono circa 300–450 g; qui calcoliamo 350 g.</p>", "seo": {"title": "Ricotta casalinga di latte intero, senza pressatura", "description": "Prepara ricotta morbida di latte e limone per ripieni o colazioni. Foto di coagulazione e scolatura delicata, resa indicativa e conservazione in frigorifero.", "author": "Néstor Bastidas", "image_alt": "Ricotta casalinga di latte intero, senza pressatura", "image_variants": ["https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-1x1.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-4x3.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-16x9.webp"], "faq": [{"q": "Posso usare solo siero?", "a": "Non con queste dosi: proteine e acidità sono diverse. La ricetta è formulata per latte."}, {"q": "Perché è secca?", "a": "Scolatura lunga, pressione o bollore forte asciugano i fiocchi. Scola meno e senza pesi."}], "additional_time_minutes": 160}}, {"language": "ja", "slug": "homemade-whole-milk-ricotta", "total_time_minutes": 190, "summary": "牛乳とレモンで作るレケソンで、全乳リコッタのように柔らかく粒が残ります。乳清だけを使う伝統製法とは異なります。牛乳2 Lで約300〜450 g、ここでは350 gを想定します。", "content_html": "<p>牛乳とレモンで作るレケソンで、全乳リコッタのように柔らかく粒が残ります。乳清だけを使う伝統製法とは異なります。牛乳2 Lで約300〜450 g、ここでは350 gを想定します。</p>", "seo": {"title": "牛乳とレモンで作る柔らかな自家製リコッタ", "description": "全乳とレモンで作る、しっとり柔らかなリコッタ風チーズ。凝固と優しい水切りを写真で解説し、出来上がり量と冷蔵保存も紹介。朝食や詰め物に使えます。", "author": "Néstor Bastidas", "image_alt": "牛乳とレモンで作る柔らかな自家製リコッタ", "image_variants": ["https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-1x1.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-4x3.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-16x9.webp"], "faq": [{"q": "乳清だけで作れますか。", "a": "この分量では作れません。たんぱく質や酸度が違います。このレシピは牛乳用です。"}, {"q": "ぱさつくのはなぜですか。", "a": "水切りしすぎ、圧搾、強い沸騰が原因になります。重石を使わず短く水切りします。"}], "additional_time_minutes": 160}}, {"language": "pt", "slug": "ricota-caseira-de-leite", "total_time_minutes": 190, "summary": "Este requesón de leite integral e limão fica solto e úmido, semelhante à ricota de leite. Não é a ricota tradicional feita só de soro. Dois litros rendem cerca de 300–450 g; calculamos 350 g.", "content_html": "<p>Este requesón de leite integral e limão fica solto e úmido, semelhante à ricota de leite. Não é a ricota tradicional feita só de soro. Dois litros rendem cerca de 300–450 g; calculamos 350 g.</p>", "seo": {"title": "Ricota caseira de leite, macia e sem prensar", "description": "Faça ricota caseira de leite e limão, macia para recheios ou café da manhã. Fotos da coagulação e drenagem, rendimento aproximado e conservação na geladeira.", "author": "Néstor Bastidas", "image_alt": "Ricota caseira de leite, macia e sem prensar", "image_variants": ["https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-1x1.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-4x3.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-16x9.webp"], "faq": [{"q": "Posso usar só soro?", "a": "Não nessas quantidades: proteínas e acidez diferem. Esta receita foi formulada para leite."}, {"q": "Por que fica seca?", "a": "Drenagem longa, pressão ou fervura forte secam os flocos. Escorra menos, sem peso."}], "additional_time_minutes": 160}}, {"language": "es", "slug": "queso-crema-casero", "total_time_minutes": 175, "summary": "Un queso fresco de acidificación rápida, triturado hasta quedar untable. No lleva cultivo ni espesantes. Con leche y crema salen aproximadamente 350–450 g; calculamos 400 g. Necesitas termómetro, colador con tela y procesadora.", "content_html": "<p>Un queso fresco de acidificación rápida, triturado hasta quedar untable. No lleva cultivo ni espesantes. Con leche y crema salen aproximadamente 350–450 g; calculamos 400 g. Necesitas termómetro, colador con tela y procesadora.</p>", "seo": {"title": "Queso crema casero para untar, con leche y crema", "description": "Haz queso crema casero para untar con leche, crema y limón. Fotos para cuajar, escurrir y triturar, con consejos de textura y conservación en nevera.", "author": "Néstor Bastidas", "image_alt": "Queso crema casero para untar, con leche y crema", "image_variants": ["https://manualdecocina.com/recetas/queso-crema-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-16x9.webp"], "faq": [{"q": "¿Por qué queda granulado?", "a": "Puede haberse secado demasiado o faltar triturado. Añade poco líquido reservado y procesa de nuevo."}, {"q": "¿Puedo usar solo leche?", "a": "Cambian grasa, rendimiento y textura. Esta fórmula incluye crema para obtener una pasta más untuosa."}], "additional_time_minutes": 145}}, {"language": "en", "slug": "homemade-spreadable-cream-cheese", "total_time_minutes": 175, "summary": "A quick acid-set fresh cheese blended until spreadable, without added cultures or thickeners. Milk and cream yield about 350–450 g; we assume 400 g. Use a thermometer, cloth-lined strainer and food processor.", "content_html": "<p>A quick acid-set fresh cheese blended until spreadable, without added cultures or thickeners. Milk and cream yield about 350–450 g; we assume 400 g. Use a thermometer, cloth-lined strainer and food processor.</p>", "seo": {"title": "Homemade spreadable cream cheese with milk and cream", "description": "Make quick spreadable cream cheese with milk, cream and lemon. Photos show setting, draining and blending, with texture tips and refrigerator storage.", "author": "Néstor Bastidas", "image_alt": "Homemade spreadable cream cheese with milk and cream", "image_variants": ["https://manualdecocina.com/recetas/queso-crema-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-16x9.webp"], "faq": [{"q": "Why is it grainy?", "a": "It may be over-drained or under-blended. Add a little reserved liquid and process again."}, {"q": "Can I use milk alone?", "a": "Fat, yield and texture change. This formula includes cream for a richer spread."}], "additional_time_minutes": 145}}, {"language": "de", "slug": "streichfrischkaese-selber-machen", "total_time_minutes": 175, "summary": "Ein schnell gesäuerter Frischkäse, der ohne zugesetzte Kulturen oder Verdickungsmittel glatt püriert wird. Milch und Sahne ergeben etwa 350–450 g; gerechnet wird mit 400 g. Du brauchst Thermometer, Tuch, Sieb und Küchenmaschine.", "content_html": "<p>Ein schnell gesäuerter Frischkäse, der ohne zugesetzte Kulturen oder Verdickungsmittel glatt püriert wird. Milch und Sahne ergeben etwa 350–450 g; gerechnet wird mit 400 g. Du brauchst Thermometer, Tuch, Sieb und Küchenmaschine.</p>", "seo": {"title": "Streichfrischkäse aus Milch und Sahne selber machen", "description": "Schnellen Streichfrischkäse aus Milch, Sahne und Zitrone machen. Fotos erklären Gerinnen, Abtropfen und Pürieren sowie Konsistenz und gekühlte Aufbewahrung.", "author": "Néstor Bastidas", "image_alt": "Streichfrischkäse aus Milch und Sahne selber machen", "image_variants": ["https://manualdecocina.com/recetas/queso-crema-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-16x9.webp"], "faq": [{"q": "Warum bleibt er körnig?", "a": "Möglicherweise zu trocken oder zu kurz püriert. Etwas Flüssigkeit zugeben und weiterpürieren."}, {"q": "Geht es nur mit Milch?", "a": "Fett, Menge und Konsistenz ändern sich. Dieses Rezept enthält Sahne für mehr Cremigkeit."}], "additional_time_minutes": 145}}, {"language": "fr", "slug": "fromage-frais-a-tartiner-maison", "total_time_minutes": 175, "summary": "Un fromage frais acidifié rapidement puis mixé, sans ferments ajoutés ni épaississant. Lait et crème donnent environ 350–450 g ; nous comptons 400 g. Prévoyez thermomètre, tissu, passoire et robot.", "content_html": "<p>Un fromage frais acidifié rapidement puis mixé, sans ferments ajoutés ni épaississant. Lait et crème donnent environ 350–450 g ; nous comptons 400 g. Prévoyez thermomètre, tissu, passoire et robot.</p>", "seo": {"title": "Fromage frais maison à tartiner, lait et crème", "description": "Faites un fromage frais à tartiner avec lait, crème et citron. Photos du caillage, de l'égouttage et du mixage, conseils de texture et conservation au frais.", "author": "Néstor Bastidas", "image_alt": "Fromage frais maison à tartiner, lait et crème", "image_variants": ["https://manualdecocina.com/recetas/queso-crema-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-16x9.webp"], "faq": [{"q": "Pourquoi est-il granuleux ?", "a": "Il peut être trop égoutté ou insuffisamment mixé. Ajoutez un peu de liquide et mixez à nouveau."}, {"q": "Puis-je utiliser seulement du lait ?", "a": "Matière grasse, rendement et texture changent. La crème apporte ici de l'onctuosité."}], "additional_time_minutes": 145}}, {"language": "it", "slug": "formaggio-cremoso-spalmabile-casalingo", "total_time_minutes": 175, "summary": "Un formaggio fresco acidificato rapidamente e frullato, senza fermenti aggiunti o addensanti. Latte e panna rendono circa 350–450 g; calcoliamo 400 g. Servono termometro, telo, colino e robot da cucina.", "content_html": "<p>Un formaggio fresco acidificato rapidamente e frullato, senza fermenti aggiunti o addensanti. Latte e panna rendono circa 350–450 g; calcoliamo 400 g. Servono termometro, telo, colino e robot da cucina.</p>", "seo": {"title": "Formaggio cremoso da spalmare fatto in casa", "description": "Prepara formaggio spalmabile con latte, panna e limone. Foto di coagulazione, scolatura e frullatura, con consigli sulla consistenza e conservazione in frigo.", "author": "Néstor Bastidas", "image_alt": "Formaggio cremoso da spalmare fatto in casa", "image_variants": ["https://manualdecocina.com/recetas/queso-crema-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-16x9.webp"], "faq": [{"q": "Perché è granuloso?", "a": "Può essere troppo scolato o poco frullato. Aggiungi poco liquido e frulla ancora."}, {"q": "Posso usare solo latte?", "a": "Cambiano grassi, resa e consistenza. Questa formula include panna per maggiore cremosità."}], "additional_time_minutes": 145}}, {"language": "ja", "slug": "homemade-spreadable-cream-cheese", "total_time_minutes": 175, "summary": "酸で短時間に固め、滑らかになるまで撹拌するフレッシュチーズです。菌や増粘剤は加えません。牛乳とクリームから約350〜450 g、ここでは400 gを想定します。温度計、布、ざる、フードプロセッサーが必要です。", "content_html": "<p>酸で短時間に固め、滑らかになるまで撹拌するフレッシュチーズです。菌や増粘剤は加えません。牛乳とクリームから約350〜450 g、ここでは400 gを想定します。温度計、布、ざる、フードプロセッサーが必要です。</p>", "seo": {"title": "牛乳とクリームで作る自家製クリームチーズ風スプレッド", "description": "牛乳、クリーム、レモンで作る塗りやすいフレッシュチーズ。凝固、水切り、なめらかにする工程を写真で解説し、食感の調整と冷蔵保存の目安も紹介します。", "author": "Néstor Bastidas", "image_alt": "牛乳とクリームで作る自家製クリームチーズ風スプレッド", "image_variants": ["https://manualdecocina.com/recetas/queso-crema-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-16x9.webp"], "faq": [{"q": "粒が残るのはなぜですか。", "a": "水切りしすぎか撹拌不足が考えられます。残した液体を少し加え、もう一度混ぜます。"}, {"q": "牛乳だけでも作れますか。", "a": "脂肪分、量、食感が変わります。この配合では滑らかさのためクリームを使います。"}], "additional_time_minutes": 145}}, {"language": "pt", "slug": "queijo-cremoso-caseiro-para-passar", "total_time_minutes": 175, "summary": "Queijo fresco de acidificação rápida, batido até ficar cremoso, sem culturas ou espessantes adicionados. Leite e creme rendem cerca de 350–450 g; calculamos 400 g. Use termômetro, pano, peneira e processador.", "content_html": "<p>Queijo fresco de acidificação rápida, batido até ficar cremoso, sem culturas ou espessantes adicionados. Leite e creme rendem cerca de 350–450 g; calculamos 400 g. Use termômetro, pano, peneira e processador.</p>", "seo": {"title": "Queijo cremoso caseiro com leite e creme de leite", "description": "Faça queijo cremoso para passar com leite, creme e limão. Fotos mostram coagulação, drenagem e processamento, com dicas de textura e conservação na geladeira.", "author": "Néstor Bastidas", "image_alt": "Queijo cremoso caseiro com leite e creme de leite", "image_variants": ["https://manualdecocina.com/recetas/queso-crema-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-16x9.webp"], "faq": [{"q": "Por que fica granulado?", "a": "Pode ter escorrido demais ou faltado processamento. Acrescente pouco líquido reservado e bata novamente."}, {"q": "Posso usar só leite?", "a": "Gordura, rendimento e textura mudam. A fórmula inclui creme para maior cremosidade."}], "additional_time_minutes": 145}}, {"language": "es", "slug": "mozzarella-casera", "total_time_minutes": 120, "summary": "Esta mozzarella fresca se hace con leche pasteurizada no UHT, ácido cítrico alimentario y cuajo. Rinde unos 400–500 g con 4 litros. Necesitas termómetro, báscula, jeringa graduada y guantes alimentarios resistentes al calor. Reserva unos 120 minutos; la leche puede variar el resultado.", "content_html": "<p>Esta mozzarella fresca se hace con leche pasteurizada no UHT, ácido cítrico alimentario y cuajo. Rinde unos 400–500 g con 4 litros. Necesitas termómetro, báscula, jeringa graduada y guantes alimentarios resistentes al calor. Reserva unos 120 minutos; la leche puede variar el resultado.</p>", "seo": {"title": "Mozzarella casera con leche, cuajo y ácido cítrico", "description": "Haz mozzarella fresca en casa con cuajo y ácido cítrico. Seis pasos con fotos, leche adecuada, temperaturas de cuajado e hilado y consejos si no estira.", "author": "Néstor Bastidas", "image_alt": "Mozzarella casera con leche, cuajo y ácido cítrico", "image_variants": ["https://manualdecocina.com/recetas/mozzarella-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-16x9.webp"], "faq": [{"q": "¿Se hace solo con vinagre?", "a": "Esta ficha usa cuajo y ácido cítrico. Cortar leche con vinagre no garantiza una mozzarella que hile."}, {"q": "¿Por qué se rompe al estirar?", "a": "Puede estar fría o tener acidez inadecuada. Recalienta suavemente una porción; si sigue rompiéndose, no fuerces todo el lote."}], "additional_time_minutes": 75}}, {"language": "en", "slug": "homemade-fresh-mozzarella", "total_time_minutes": 120, "summary": "Use pasteurized non-UHT milk, food-grade citric acid and rennet. Four litres yield roughly 400–500 g. You need a thermometer, scale, graduated syringe and food-safe heat-resistant gloves. Allow about 120 minutes; milk affects the result.", "content_html": "<p>Use pasteurized non-UHT milk, food-grade citric acid and rennet. Four litres yield roughly 400–500 g. You need a thermometer, scale, graduated syringe and food-safe heat-resistant gloves. Allow about 120 minutes; milk affects the result.</p>", "seo": {"title": "Homemade mozzarella with rennet and citric acid", "description": "Make fresh mozzarella with rennet and citric acid. Six photo steps explain milk choice, setting and stretching temperatures, cooling and troubleshooting.", "author": "Néstor Bastidas", "image_alt": "Homemade mozzarella with rennet and citric acid", "image_variants": ["https://manualdecocina.com/recetas/mozzarella-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-16x9.webp"], "faq": [{"q": "Can I use vinegar alone?", "a": "This recipe uses rennet and citric acid. Vinegar-set milk does not reliably produce stretching mozzarella."}, {"q": "Why does it tear?", "a": "It may be cold or have unsuitable acidity. Gently rewarm one portion; if it still tears, do not force the entire batch."}], "additional_time_minutes": 75}}, {"language": "de", "slug": "mozzarella-selber-machen", "total_time_minutes": 120, "summary": "Verwende pasteurisierte Milch, keine H-Milch, lebensmittelechte Zitronensäure und Lab. Vier Liter ergeben etwa 400–500 g. Thermometer, Waage, graduierte Spritze und lebensmittelechte Hitzeschutzhandschuhe bereitlegen. Plane rund 120 Minuten ein; die Milch beeinflusst das Ergebnis.", "content_html": "<p>Verwende pasteurisierte Milch, keine H-Milch, lebensmittelechte Zitronensäure und Lab. Vier Liter ergeben etwa 400–500 g. Thermometer, Waage, graduierte Spritze und lebensmittelechte Hitzeschutzhandschuhe bereitlegen. Plane rund 120 Minuten ein; die Milch beeinflusst das Ergebnis.</p>", "seo": {"title": "Mozzarella mit Lab und Zitronensäure selber machen", "description": "Frischen Mozzarella mit Lab und Zitronensäure herstellen. Sechs Schrittfotos erklären Milchwahl, Temperaturen beim Gerinnen und Ziehen sowie das Abkühlen.", "author": "Néstor Bastidas", "image_alt": "Mozzarella mit Lab und Zitronensäure selber machen", "image_variants": ["https://manualdecocina.com/recetas/mozzarella-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-16x9.webp"], "faq": [{"q": "Geht es nur mit Essig?", "a": "Hier werden Lab und Zitronensäure verwendet. Essig allein liefert nicht zuverlässig ziehfähigen Mozzarella."}, {"q": "Warum reißt der Käse?", "a": "Er kann zu kalt sein oder eine ungeeignete Säure haben. Eine Portion vorsichtig nachwärmen und nicht die ganze Menge mit Gewalt ziehen."}], "additional_time_minutes": 75}}, {"language": "fr", "slug": "mozzarella-fraiche-maison", "total_time_minutes": 120, "summary": "Utilisez du lait pasteurisé non UHT, de l'acide citrique alimentaire et de la présure. Quatre litres donnent environ 400–500 g. Prévoyez thermomètre, balance, seringue graduée et gants alimentaires résistants à la chaleur. Comptez environ 120 minutes ; le lait influence le résultat.", "content_html": "<p>Utilisez du lait pasteurisé non UHT, de l&#x27;acide citrique alimentaire et de la présure. Quatre litres donnent environ 400–500 g. Prévoyez thermomètre, balance, seringue graduée et gants alimentaires résistants à la chaleur. Comptez environ 120 minutes ; le lait influence le résultat.</p>", "seo": {"title": "Mozzarella maison à la présure et à l'acide citrique", "description": "Faites une mozzarella fraîche à la présure et à l'acide citrique. Six étapes en photos expliquent le lait adapté, le caillage, le filage et le refroidissement.", "author": "Néstor Bastidas", "image_alt": "Mozzarella maison à la présure et à l'acide citrique", "image_variants": ["https://manualdecocina.com/recetas/mozzarella-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-16x9.webp"], "faq": [{"q": "Peut-on utiliser seulement du vinaigre ?", "a": "Cette recette emploie présure et acide citrique. Le vinaigre seul ne garantit pas une mozzarella filante."}, {"q": "Pourquoi se déchire-t-elle ?", "a": "Le caillé peut être froid ou mal acidifié. Réchauffez doucement une portion ; si elle se déchire encore, ne forcez pas le lot."}], "additional_time_minutes": 75}}, {"language": "it", "slug": "mozzarella-fatta-in-casa", "total_time_minutes": 120, "summary": "Usa latte pastorizzato non UHT, acido citrico alimentare e caglio. Quattro litri rendono circa 400–500 g. Servono termometro, bilancia, siringa graduata e guanti alimentari resistenti al calore. Riserva circa 120 minuti; il tipo di latte influenza la riuscita.", "content_html": "<p>Usa latte pastorizzato non UHT, acido citrico alimentare e caglio. Quattro litri rendono circa 400–500 g. Servono termometro, bilancia, siringa graduata e guanti alimentari resistenti al calore. Riserva circa 120 minuti; il tipo di latte influenza la riuscita.</p>", "seo": {"title": "Mozzarella fatta in casa con caglio e acido citrico", "description": "Prepara mozzarella fresca con caglio e acido citrico. Sei passaggi fotografati spiegano latte adatto, temperature di coagulazione e filatura e raffreddamento.", "author": "Néstor Bastidas", "image_alt": "Mozzarella fatta in casa con caglio e acido citrico", "image_variants": ["https://manualdecocina.com/recetas/mozzarella-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-16x9.webp"], "faq": [{"q": "Basta l'aceto?", "a": "Qui servono caglio e acido citrico. Latte coagulato con solo aceto non garantisce mozzarella filante."}, {"q": "Perché si spezza?", "a": "Può essere fredda o avere acidità inadatta. Riscalda piano una porzione; se si rompe ancora, non forzare tutto il lotto."}], "additional_time_minutes": 75}}, {"language": "ja", "slug": "homemade-fresh-mozzarella", "total_time_minutes": 120, "summary": "超高温殺菌ではない殺菌牛乳、食品用クエン酸、レンネットを使います。4 Lで約400〜500 g。温度計、はかり、目盛り付きシリンジ、食品用耐熱手袋が必要です。約120分を見込みます。牛乳によって仕上がりが変わります。", "content_html": "<p>超高温殺菌ではない殺菌牛乳、食品用クエン酸、レンネットを使います。4 Lで約400〜500 g。温度計、はかり、目盛り付きシリンジ、食品用耐熱手袋が必要です。約120分を見込みます。牛乳によって仕上がりが変わります。</p>", "seo": {"title": "レンネットとクエン酸で作る自家製モッツァレラ", "description": "殺菌牛乳、食品用クエン酸、レンネットで作るモッツァレラ。6工程の写真で牛乳の選び方、凝固、加熱、引き伸ばし、冷却を解説。伸びないときの確認点も紹介します。", "author": "Néstor Bastidas", "image_alt": "レンネットとクエン酸で作る自家製モッツァレラ", "image_variants": ["https://manualdecocina.com/recetas/mozzarella-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-16x9.webp"], "faq": [{"q": "酢だけで作れますか。", "a": "このレシピはレンネットとクエン酸を使います。酢だけで固めても、伸びるモッツァレラになるとは限りません。"}, {"q": "伸ばすと切れるのはなぜですか。", "a": "温度が低いか酸度が合わないことがあります。少量を温め直し、それでも切れるなら全量を無理に引っ張りません。"}], "additional_time_minutes": 75}}, {"language": "pt", "slug": "mozzarella-caseira", "total_time_minutes": 120, "summary": "Use leite pasteurizado não UHT, ácido cítrico alimentício e coalho. Quatro litros rendem cerca de 400–500 g. Tenha termômetro, balança, seringa graduada e luvas alimentícias resistentes ao calor. Reserve cerca de 120 minutos; o leite influencia o resultado.", "content_html": "<p>Use leite pasteurizado não UHT, ácido cítrico alimentício e coalho. Quatro litros rendem cerca de 400–500 g. Tenha termômetro, balança, seringa graduada e luvas alimentícias resistentes ao calor. Reserve cerca de 120 minutos; o leite influencia o resultado.</p>", "seo": {"title": "Mozzarella caseira com coalho e ácido cítrico", "description": "Faça mozzarella fresca com coalho e ácido cítrico. Seis etapas com fotos explicam leite adequado, temperaturas de coagulação e filagem e resfriamento.", "author": "Néstor Bastidas", "image_alt": "Mozzarella caseira com coalho e ácido cítrico", "image_variants": ["https://manualdecocina.com/recetas/mozzarella-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-16x9.webp"], "faq": [{"q": "Dá para fazer só com vinagre?", "a": "Esta receita usa coalho e ácido cítrico. Leite cortado apenas com vinagre não garante mozzarella que file."}, {"q": "Por que rasga ao esticar?", "a": "Pode estar fria ou com acidez inadequada. Reaqueça uma porção com cuidado; se ainda rasgar, não force o lote todo."}], "additional_time_minutes": 75}}]$j$::jsonb)) UPDATE public.recipes r SET total_time_minutes=(x->>'total_time_minutes')::int, summary=x->>'summary',content_html=x->>'content_html',seo=x->'seo' FROM data WHERE r.language=x->>'language' AND r.slug=x->>'slug' RETURNING r.language,r.slug,r.total_time_minutes;